window.VID_FILES = {"vid/__init__.py": "\"\"\"Vid: a local guard between an AI agent and its model.\"\"\"\n\n__version__ = \"0.1.0.dev0\"\n", "vid/defaults.toml": "# Vid default configuration. Every value here is an initial value.\n# The user's file (see `vid paths`) overrides any key it sets.\n# Values listed under [constants.not_set] have no value yet: Vid shows\n# them as \"not set\" and never invents one (docs/REFERENCE.md, Sec 14).\n\n[server]\nhost = \"127.0.0.1\"\nport = 8787            # agents point their base URL here\ncontrol_port = 8788    # local channel to the Vid window, token-protected\n\n[upstream.openai]\n# OpenAI-compatible API (OpenAI, llama.cpp server, Ollama, Groq, Mistral...).\n# An agent calling http://127.0.0.1:8787/v1/<path> reaches <base_url>/<path>.\nbase_url = \"https://api.openai.com/v1\"\napi_key = \"\"           # empty: the agent's own key is passed on\n# The environment variable VID_OPENAI_API_KEY, when set, wins over api_key.\n\n[upstream.anthropic]\n# An agent calling http://127.0.0.1:8787/anthropic/<path> reaches <base_url>/<path>.\nbase_url = \"https://api.anthropic.com\"\napi_key = \"\"           # VID_ANTHROPIC_API_KEY wins when set\n\n[upstream.timeouts]\nconnect_s = 10.0\n# No read timeout by default: a model may think for minutes between tokens.\nread_s = 0.0\n\n[constants]\n# REFERENCE.md Sec 14. Not used by phase A; listed so the UI can show them.\nAXIS_DEAD_ZONE = 0.30\nRISK_ELEVATED_T = 0.35\nRISK_CRITICAL_T = 0.65\nUNREADABLE_T = 0.80\nSHAPE_MIN_OBS = 30\nHOLD_MIN_OBS = 30\nRUN_N = 3\nTHETA_NOMINAL = 30\nTHETA_BAND = [25, 35]\nFIRST_CONTACT_W_O = 0.15\nFIRST_CONTACT_W_F = 0.15\n\n[constants.not_set]\nnames = [\n  \"CLUSTER_T\", \"AUTH_MIN_TOTAL\", \"TIMING_MIN_INTERVALS\", \"BASELINE_MIN_N\",\n  \"UNREADABLE_SCALE\", \"SEGMENT_MIN_LEN\", \"PRIVESC_CAP\", \"K_C\", \"K_N\",\n  \"L_defaults\",\n]\n\n[input_layer]\n# Basic layer (docs/REFERENCE.md Sec 3). Thresholds for the normalization\n# steps and the depth of repeated decoding (E-57).\nmax_depth = 5             # decoding repeated at most this many times\nmax_chars = 200000        # longer payloads are analysed in their first part\noverlay_min = 2           # line-drawing marks before E-43 is reported\nzalgo_marks = 3           # combining marks on one letter before it is zalgo\nhomoglyph_latin_share = 0.7   # Latin share of a text for whole look-alike words to count\nupside_down_min = 3       # distinctive upside-down letters in a run\nspaced_letters_min = 5    # letters spread with spaces before they are joined\nexotic_space_min = 3      # unusual spaces before E-37 is reported on its own\nsplat_min_parts = 5       # pieces of a word broken by symbols\nvertical_min_lines = 5    # one-letter lines before text counts as vertical\ncase_flip_ratio = 0.6     # share of case changes inside a word\ncase_words_min = 1        # such words before E-13 is reported\n", "vid/input_layer/__init__.py": "\"\"\"The input layer, \"DL1\" (docs/REFERENCE.md Sec 3): makes input readable.\n\n    analyze(text, provenance=\"external\") -> Analysis\n\nDeterministic and dependency-free (it also runs in the browser). In the free\nVid it only observes: the model still receives the original (decision of\n13 Oct 2026); what was found is shown to the operator.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport tomllib\nfrom functools import lru_cache\nfrom importlib import resources\n\nfrom vid.input_layer import control_tokens, decoders, normalize, signals as signal_mod, structure\nfrom vid.input_layer.codes import ALL_NAMES, ATTRIBUTION, BASIC_LAYER\nfrom vid.input_layer.types import Analysis, Finding, short\n\n__all__ = [\"analyze\", \"Analysis\", \"Finding\", \"BASIC_LAYER\", \"ALL_NAMES\", \"ATTRIBUTION\", \"settings\"]\n\n\n@lru_cache(maxsize=1)\ndef _default_settings() -> dict:\n    data = tomllib.loads(resources.files(\"vid\").joinpath(\"defaults.toml\").read_text(\"utf-8\"))\n    return dict(data[\"input_layer\"])\n\n\ndef settings(over: dict | None = None) -> dict:\n    s = dict(_default_settings())\n    if over:\n        s.update(over)\n    return s\n\n\ndef _process(text: str, s: dict, depth: int, chain: list[str], findings: list[Finding], own: bool) -> str:\n    text, f = normalize.normalize(text, s)\n    findings.extend(f)\n    if not own:\n        text, f = control_tokens.remove(text)\n        findings.extend(f)\n    text, f = structure.flatten(text)\n    findings.extend(f)\n    if depth >= s[\"max_depth\"]:\n        return text\n    for code, excerpt, decoded in decoders.decode_once(text):\n        inner: list[Finding] = []\n        plain = _process(decoded, s, depth + 1, chain + [code], inner, own)\n        findings.append(Finding(code, _DECODE_DETAIL.get(code, \"Encoded text decoded.\"), short(excerpt), short(plain)))\n        findings.extend(inner)\n        if inner and any(i.group == \"decoder\" for i in inner):\n            layers = [code] + [i.code for i in inner if i.group == \"decoder\"]\n            findings.append(Finding(\"PIT-E-57\", f\"Text encoded in {len(layers)} layers, undone one after another ({' → '.join(BASIC_LAYER[c] for c in layers)}).\",\n                                    short(excerpt), short(plain), chain=layers))\n        text = text.replace(excerpt, plain, 1)\n    return text\n\n\n_DECODE_DETAIL = {\n    \"PIT-E-01\": \"Numbers standing for letters (A=1 … Z=26) decoded.\",\n    \"PIT-E-06\": \"Baconian cipher (groups of A and B) decoded.\",\n    \"PIT-E-07\": \"Base64 decoded.\",\n    \"PIT-E-08\": \"Binary decoded.\",\n    \"PIT-E-21\": \"Hexadecimal decoded.\",\n    \"PIT-E-22\": \"HTML entities decoded.\",\n    \"PIT-E-30\": \"Morse code decoded.\",\n    \"PIT-E-31\": \"NATO phonetic alphabet decoded.\",\n    \"PIT-E-33\": \"Rail-fence cipher found by search and decoded.\",\n    \"PIT-E-36\": \"Reversed text turned around.\",\n    \"PIT-E-44\": \"Tap code decoded.\",\n    \"PIT-E-46\": \"URL encoding decoded.\",\n    \"PIT-E-55\": \"Base32, Base58 or Base85 decoded.\",\n    \"PIT-E-56\": \"Character codes (U+…, &#…;, numbers) turned into letters.\",\n    \"PIT-E-58\": \"Compressed data unpacked.\",\n    \"PIT-E-62\": \"Text in a legacy character set (UTF-7, quoted-printable, wrong charset) decoded.\",\n}\n\n\ndef _dedupe(findings: list[Finding]) -> list[Finding]:\n    seen, out = set(), []\n    for f in findings:\n        key = (f.code, f.excerpt, f.revealed)\n        if key not in seen:\n            seen.add(key)\n            out.append(f)\n    return out\n\n\ndef analyze(text: str, provenance: str = \"external\", over: dict | None = None) -> Analysis:\n    \"\"\"Undo what hides text. `provenance`: system | operator | principal | external | model.\n    Control tokens are removed from everything that is not the system's own.\"\"\"\n    s = settings(over)\n    raw = text\n    findings: list[Finding] = []\n    readable = _process(text[: s[\"max_chars\"]], s, 0, [], findings, own=(provenance == \"system\"))\n    readable = readable.strip()\n    # Surface signals read the undone text; they observe, they do not judge.\n    findings.extend(signal_mod.signals(readable))\n    return Analysis(raw=raw, readable=readable, findings=_dedupe(findings), provenance=provenance)\n", "vid/input_layer/codes.py": "\"\"\"The attack codes this layer answers (docs/REFERENCE.md Sec 15, basic layer).\n\nCodes and names: Haddix, J. (2026). Arcanum Prompt Injection Taxonomy (v1.6.1).\nArcanum Information Security. https://www.arcanum-sec.com/pitax (CC BY 4.0).\n\"\"\"\n\nATTRIBUTION = (\"Haddix, J. (2026). Arcanum Prompt Injection Taxonomy (v1.6.1). \"\n               \"Arcanum Information Security. https://www.arcanum-sec.com/pitax (CC BY 4.0)\")\n\nNORMALIZATION = {\n    \"PIT-E-11\": \"Braille\",\n    \"PIT-E-12\": \"Bubble/Enclosed Text\",\n    \"PIT-E-13\": \"Case Changing\",\n    \"PIT-E-19\": \"Fullwidth\",\n    \"PIT-E-20\": \"Homoglyphs\",\n    \"PIT-E-23\": \"Invisible Text\",\n    \"PIT-E-28\": \"Metacharacter Confusion\",\n    \"PIT-E-29\": \"Mathematical Unicode\",\n    \"PIT-E-34\": \"Regional Indicators\",\n    \"PIT-E-37\": \"Spaces/Whitespace\",\n    \"PIT-E-38\": \"Splats\",\n    \"PIT-E-40\": \"Small Caps/Sub/Superscript\",\n    \"PIT-E-43\": \"Strikethrough/Underline/Overlay\",\n    \"PIT-E-45\": \"Upside Down\",\n    \"PIT-E-47\": \"Vertical Text\",\n    \"PIT-E-49\": \"Wingdings/Symbol Fonts\",\n    \"PIT-E-51\": \"Zalgo\",\n    \"PIT-E-54\": \"Bidirectional Override\",\n    \"PIT-E-59\": \"ANSI Escape Concealment\",\n}\nDECODERS = {\n    \"PIT-E-01\": \"A1Z26\",\n    \"PIT-E-06\": \"Baconian\",\n    \"PIT-E-07\": \"Base64\",\n    \"PIT-E-08\": \"Binary\",\n    \"PIT-E-21\": \"Hexadecimal\",\n    \"PIT-E-22\": \"HTML Entities\",\n    \"PIT-E-30\": \"Morse\",\n    \"PIT-E-31\": \"NATO Phonetic\",\n    \"PIT-E-33\": \"Rail Fence\",\n    \"PIT-E-36\": \"Reverse\",\n    \"PIT-E-44\": \"Tap Code\",\n    \"PIT-E-46\": \"URL Encoding\",\n    \"PIT-E-55\": \"Alternative Base Encodings\",\n    \"PIT-E-56\": \"Numeric Code-Point\",\n    \"PIT-E-57\": \"Layered Encoding\",\n    \"PIT-E-58\": \"Compression Encoding\",\n    \"PIT-E-62\": \"Legacy Charset\",\n}\nSTRUCTURE = {\n    \"PIT-E-18\": \"Graph Nodes\",\n    \"PIT-E-25\": \"JSON\",\n    \"PIT-E-27\": \"Markdown\",\n    \"PIT-E-50\": \"XML\",\n}\nCONTROL_TOKENS = {\n    \"PIT-T-07\": \"End Sequences\",\n    \"PIT-T-48\": \"Special-Token Injection\",\n}\n\nBASIC_LAYER = {**NORMALIZATION, **DECODERS, **STRUCTURE, **CONTROL_TOKENS}\nassert len(BASIC_LAYER) == 42, len(BASIC_LAYER)\n\nGROUP = {**{c: \"normalization\" for c in NORMALIZATION}, **{c: \"decoder\" for c in DECODERS},\n         **{c: \"structure\" for c in STRUCTURE}, **{c: \"control_token\" for c in CONTROL_TOKENS}}\n\n# Surface signals Vid also shows (not Arcanum PIT codes).\nSIGNALS = {\n    \"SIG-ACROSTIC\": \"Acrostic (hidden in first letters)\",\n    \"SIG-TRANSFORM-EXEC\": \"Transform-and-execute instruction\",\n}\nALL_NAMES = {**BASIC_LAYER, **SIGNALS}\n", "vid/input_layer/textscore.py": "\"\"\"Does a string read like language? Used to accept or reject a decoding, so\nidentifiers, hashes, keys, code and random tokens are not \"decoded\" into\nnonsense (docs/REFERENCE.md Sec 3, COST).\n\nThe main signal is the letter-pair structure of the text: real English and\nSerbian (Latin) words are built from a small set of common letter pairs, while\nhashes, keys and random strings are full of rare pairs (\"xq\", \"zk\", \"vr\").\nThis is the letter-pair idea of Sec 7, in a compact form. A short list of\ncommon words adds confidence. Phase 2 replaces this with the full\ndeclared-language letter tables; the interface stays.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\n# Common English letter pairs plus the ones Serbian (Latin) adds. A real word's\n# adjacent letters are nearly all in here; a random token's are mostly not.\n_COMMON_BIGRAMS = frozenset((\n    \"th he in er an re on at en nd ti es or te of ed is it al ar st to nt ng se ha as ou io le ve co me de hi ri \"\n    \"ro ic ne ea ra ce li ch ll be ma si om ur ca el ta la ns di fo ho pe ec pr ne nc \"\n    \"wa sh et na ro ol pa op ad ys ir si tr su ea ee ss oo mm tt ff pp rr nn cc dd gg \"\n    \"pl cl bl fl gl sl sp st sc sk sm sn sw tw dr fr gr pr tr br cr wr \"\n    \"ab ac ad ag ak am ap ar as at av aw ay \"\n    \"eb ec ed ef eg ek el em en ep er es et ev ew ex ey \"\n    \"ib ic id if ig ik il im in ip ir is it iv \"\n    \"ob oc od of og ok ol om on op or os ot ov ow oy \"\n    \"ub uc ud uf ug uk ul um un up ur us ut uv \"\n    \"do go ho jo ko lo mo no po so wo yo \"\n    \"ba ca da fa ga ja ka pa va wa ya za \"\n    \"ja je ji jo ju lj nj dj \"\n    \"ko ni po ti vi za sa mo bi da ne se te to tu ra \"\n).split())\n\n\n_EN = (\"the be to of and a in that have i it for not on with he as you do at this but his by from they we say \"\n       \"her she or an will my one all would there their what so up out if about who get which go me when make can \"\n       \"like time no just him know take into year good some could them see other than then now look only come its \"\n       \"over think also after use two how first work well way even new want because any give day most us are was \"\n       \"ignore previous instructions system prompt assistant please send show read file data key password quick \"\n       \"brown fox jumps over lazy dog pack box jugs note text hello world review report summary title end task\").split()\n_SR = (\"je i u da se na za ne to sa od su sam si smo ste kao ali ili ako jer kad kada sve što sta koji koja koje \"\n       \"nije biti bio bila bilo ima imam nema mogu može treba hoću reci kaži pošalji obriši lozinka ključ sistem \"\n       \"uputstvo zanemari prethodna pravila poruka fajl podatke dobar dan kako ste hvala molim zdravo ovo taj \"\n       \"danas sutra možete poslati izveštaj petka unapred pozdrav\").split()\nWORDS = frozenset(_EN) | frozenset(_SR)\n\n_VOWELS = set(\"aeiouyàáâãäåèéêëìíîïòóôõöùúûüçćčđšžабвгдђежзијклмнопрстћуфхцчџш\")\n_TOKEN = re.compile(r\"[^\\W\\d_]+\", re.UNICODE)\n\n\ndef _bigram_coverage(token: str) -> float:\n    \"\"\"Share of adjacent letter pairs that are common in English/Serbian.\"\"\"\n    t = token.lower()\n    pairs = [t[i:i + 2] for i in range(len(t) - 1)]\n    if not pairs:\n        return 1.0 if t in WORDS or (len(t) == 1 and t in _VOWELS) else 0.0\n    return sum(p in _COMMON_BIGRAMS for p in pairs) / len(pairs)\n\n\ndef _vowel_ok(token: str) -> bool:\n    \"\"\"Real words of 3+ letters almost always contain a vowel and are not all vowels.\"\"\"\n    t = token.lower()\n    if len(t) < 3:\n        return True\n    vowels = sum(c in _VOWELS for c in t)\n    return 0 < vowels < len(t)\n\n\ndef score(s: str) -> float:\n    \"\"\"0 (noise) .. 1 (ordinary language).\"\"\"\n    tokens = [t.lower() for t in _TOKEN.findall(s)]\n    if not tokens:\n        return 0.0\n    letters = sum(len(t) for t in tokens)\n    if not letters:\n        return 0.0\n    known = sum(len(t) for t in tokens if t in WORDS)\n    cover = sum(len(t) * _bigram_coverage(t) for t in tokens) / letters\n    voweled = sum(len(t) for t in tokens if _vowel_ok(t)) / letters\n    printable = sum(ch.isprintable() or ch in \"\\n\\t\" for ch in s) / len(s)\n    base = 0.6 * cover + 0.4 * voweled\n    bonus = 0.25 * known / letters\n    return round(printable * min(1.0, base + bonus), 3)\n\n\ndef known_share(s: str) -> float:\n    tokens = [t.lower() for t in _TOKEN.findall(s)]\n    letters = sum(len(t) for t in tokens)\n    return sum(len(t) for t in tokens if t in WORDS) / letters if letters else 0.0\n\n\ndef _cover(token: str) -> int:\n    \"\"\"Letters of `token` covered by known words of 2+ letters, allowing the\n    word boundaries to be missing (e.g. \"thequickfox\").\"\"\"\n    if token in WORDS:\n        return len(token)\n    n = len(token)\n    best = [0] * (n + 1)\n    for i in range(1, n + 1):\n        best[i] = best[i - 1]\n        for j in range(max(0, i - 14), i - 1):\n            w = token[j:i]\n            if len(w) >= 2 and w in WORDS:\n                best[i] = max(best[i], best[j] + (i - j))\n    return best[n]\n\n\ndef segmented_share(s: str) -> float:\n    \"\"\"Share of letters belonging to known words, even with spaces removed.\"\"\"\n    tokens = [t.lower() for t in _TOKEN.findall(s)]\n    letters = sum(len(t) for t in tokens)\n    return sum(_cover(t) for t in tokens) / letters if letters else 0.0\n\n\ndef plausible(s: str, threshold: float = 0.6, min_letters: int = 4, min_known: float = 0.0) -> bool:\n    \"\"\"True when `s` reads like language: what a decoding must produce to count.\n\n    `min_known` is kept for callers that want to require known words as well;\n    the default relies on letter-pair structure so ordinary words outside the\n    small list still pass.\n    \"\"\"\n    if sum(ch.isalpha() for ch in s) < min_letters:\n        return False\n    if known_share(s) < min_known:\n        return False\n    return score(s) >= threshold\n\n\ndef printable_text(b: bytes) -> str | None:\n    \"\"\"bytes -> str when the bytes are readable text, else None.\"\"\"\n    try:\n        s = b.decode(\"utf-8\")\n    except UnicodeDecodeError:\n        return None\n    if not s or sum(ch.isprintable() or ch in \"\\n\\r\\t\" for ch in s) / len(s) < 0.95:\n        return None\n    return s\n", "vid/input_layer/normalize.py": "\"\"\"Unicode normalization: the 19 normalization codes of the basic layer\n(docs/REFERENCE.md Sec 3, Sec 15).\n\nEvery step takes text and returns (text, findings). Legitimate text in other\nscripts is left alone: Cyrillic is a script, not a homoglyph attack, and\nmixed-language text is legitimate (Sec 3, CAUTION). Emoji sequences keep\ntheir joiners and presentation selectors.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nimport unicodedata\n\nfrom vid.input_layer.textscore import WORDS, plausible, printable_text\nfrom vid.input_layer.types import Finding, short\n\n# ---------------------------------------------------------------------------\n# E-59 ANSI escape concealment\n# ---------------------------------------------------------------------------\n_ANSI = re.compile(r\"\\x1b\\[[0-?]*[ -/]*[@-~]|\\x1b\\][^\\x07\\x1b]*(?:\\x07|\\x1b\\\\)|\\x1b[@-Z\\\\-_]\")\n_CONCEAL = re.compile(r\"\\x1b\\[(?:[0-9;]*;)?8(?:;[0-9;]*)?m(.*?)(?=\\x1b\\[|$)\", re.S)\n\n\ndef ansi(text: str, s: dict) -> tuple[str, list[Finding]]:\n    if \"\\x1b\" not in text:\n        return text, []\n    concealed = [m.group(1) for m in _CONCEAL.finditer(text) if m.group(1).strip()]\n    n = len(_ANSI.findall(text))\n    out = _ANSI.sub(\"\", text)\n    detail = f\"{n} terminal escape sequence(s) removed\"\n    if concealed:\n        detail += \"; text set to be invisible in a terminal is shown\"\n    return out, [Finding(\"PIT-E-59\", detail + \".\", short(text), short(\" \".join(concealed) or out), count=n)]\n\n\n# ---------------------------------------------------------------------------\n# E-54 bidirectional override\n# ---------------------------------------------------------------------------\n_BIDI = dict.fromkeys(map(ord, \"‪‫‬‭‮⁦⁧⁨⁩‎‏؜\"))\n\n\ndef bidi(text: str, s: dict) -> tuple[str, list[Finding]]:\n    n = sum(1 for ch in text if ord(ch) in _BIDI)\n    if not n:\n        return text, []\n    out = text.translate(_BIDI)\n    return out, [Finding(\"PIT-E-54\", f\"{n} text-direction control(s) removed; the text is shown in the order the model reads it.\",\n                         short(text), short(out), count=n)]\n\n\n# ---------------------------------------------------------------------------\n# E-23 invisible text\n# ---------------------------------------------------------------------------\n_ZERO_WIDTH = set(\"​‌‍⁠﻿᠎⁡⁢⁣⁤­͏ᅟᅠㅤﾠ឴឵\")\n_TAG = range(0xE0000, 0xE0080)\n_VS = set(range(0xFE00, 0xFE10)) | set(range(0xE0100, 0xE01F0))\n\n\ndef _is_emoji(ch: str) -> bool:\n    cp = ord(ch)\n    return 0x1F000 <= cp <= 0x1FAFF or 0x2600 <= cp <= 0x27BF or cp in (0x2764, 0x2B50, 0x2B55)\n\n\ndef _vs_value(cp: int) -> int:\n    return cp - 0xFE00 if cp < 0xFE10 else cp - 0xE0100 + 16\n\n\ndef invisible(text: str, s: dict) -> tuple[str, list[Finding]]:\n    out: list[str] = []\n    revealed: list[str] = []\n    removed = 0\n    i, n = 0, len(text)\n    while i < n:\n        ch, cp = text[i], ord(text[i])\n        # Tag characters spell ASCII invisibly (\"ASCII smuggling\").\n        if cp in _TAG:\n            j = i\n            while j < n and ord(text[j]) in _TAG:\n                j += 1\n            hidden = \"\".join(chr(ord(c) - 0xE0000) for c in text[i:j] if 0xE0020 <= ord(c) <= 0xE007E)\n            if hidden:\n                revealed.append(hidden)\n            removed += j - i\n            i = j\n            continue\n        # Runs of variation selectors after one character carry bytes.\n        if cp in _VS:\n            j = i\n            while j < n and ord(text[j]) in _VS:\n                j += 1\n            run = text[i:j]\n            prev = text[i - 1] if i else \"\"\n            legit = len(run) == 1 and (cp in (0xFE0E, 0xFE0F) or (prev and unicodedata.category(prev).startswith(\"L\")))\n            if legit:\n                out.append(ch)\n            else:\n                decoded = printable_text(bytes(_vs_value(ord(c)) for c in run))\n                if decoded:\n                    revealed.append(decoded)\n                removed += len(run)\n            i = j\n            continue\n        if ch in _ZERO_WIDTH:\n            # Zero-width joiner inside an emoji sequence is legitimate.\n            if ch == \"‍\" and i and i + 1 < n and _is_emoji(text[i - 1]) and _is_emoji(text[i + 1]):\n                out.append(ch)\n                i += 1\n                continue\n            j = i\n            while j < n and text[j] in _ZERO_WIDTH:\n                j += 1\n            run = text[i:j]\n            bits = \"\".join(\"0\" if c == \"​\" else \"1\" if c == \"‌\" else \"\" for c in run)\n            if len(bits) >= 8 and len(bits) % 8 == 0:\n                decoded = printable_text(int(bits, 2).to_bytes(len(bits) // 8, \"big\"))\n                if decoded:\n                    revealed.append(decoded)\n            removed += len(run)\n            i = j\n            continue\n        out.append(ch)\n        i += 1\n    if not removed:\n        return text, []\n    result = \"\".join(out)\n    detail = f\"{removed} invisible character(s) removed\"\n    if revealed:\n        detail += \"; they carried hidden text\"\n        result = result + \"\\n\" + \"\\n\".join(revealed)\n    return result, [Finding(\"PIT-E-23\", detail + \".\", short(text), short(\" \".join(revealed) or result), count=removed)]\n\n\n# ---------------------------------------------------------------------------\n# E-43 strikethrough/underline/overlay, E-51 zalgo\n# ---------------------------------------------------------------------------\n_OVERLAY = set(\"̴̵̶̷̸⃒⃓⃥⃦̲̳̱̠̅̿\")\n\n\ndef overlay(text: str, s: dict) -> tuple[str, list[Finding]]:\n    n = sum(1 for ch in text if ch in _OVERLAY)\n    if n < s[\"overlay_min\"]:\n        return text, []\n    out = \"\".join(ch for ch in text if ch not in _OVERLAY)\n    return out, [Finding(\"PIT-E-43\", f\"{n} line-drawing mark(s) (strikethrough, underline, overlay) removed.\", short(text), short(out), count=n)]\n\n\ndef zalgo(text: str, s: dict) -> tuple[str, list[Finding]]:\n    # No NFC first: that would fuse the first mark into the base letter (e+◌̀ -> è)\n    # and hide it. Count raw combining marks and drop the whole stack.\n    out: list[str] = []\n    stripped = 0\n    marks = 0\n    for ch in text:\n        if unicodedata.category(ch) == \"Mn\":\n            marks += 1\n            out.append(ch)\n            continue\n        if marks >= s[\"zalgo_marks\"]:\n            # drop the whole stack of marks on the previous character\n            del out[len(out) - marks:]\n            stripped += marks\n        marks = 0\n        out.append(ch)\n    if marks >= s[\"zalgo_marks\"]:\n        del out[len(out) - marks:]\n        stripped += marks\n    if not stripped:\n        return text, []\n    res = \"\".join(out)\n    return res, [Finding(\"PIT-E-51\", f\"{stripped} stacked combining mark(s) (\\\"zalgo\\\") removed.\", short(text), short(res), count=stripped)]\n\n\n# ---------------------------------------------------------------------------\n# Character folds: E-19, E-29, E-12, E-40, E-11, E-34, E-49, E-28, E-20\n# ---------------------------------------------------------------------------\n_BRAILLE = {0x01: \"a\", 0x03: \"b\", 0x09: \"c\", 0x19: \"d\", 0x11: \"e\", 0x0B: \"f\", 0x1B: \"g\", 0x13: \"h\", 0x0A: \"i\",\n            0x1A: \"j\", 0x05: \"k\", 0x07: \"l\", 0x0D: \"m\", 0x1D: \"n\", 0x15: \"o\", 0x0F: \"p\", 0x1F: \"q\", 0x17: \"r\",\n            0x0E: \"s\", 0x1E: \"t\", 0x25: \"u\", 0x27: \"v\", 0x3A: \"w\", 0x2D: \"x\", 0x3D: \"y\", 0x35: \"z\", 0x00: \" \"}\n_BRAILLE_DIGITS = dict(zip(\"abcdefghij\", \"1234567890\"))\n\n_WINGDINGS = dict(zip(\n    [\"♋\", \"♌\", \"♍\", \"♎\", \"♏\", \"♐\", \"♑\", \"♒\", \"♓\", \"🙰\", \"🙵\", \"●\", \"❍\", \"■\", \"□\", \"◻\", \"❑\", \"❒\", \"⬧\", \"◆\", \"❖\", \"⬥\", \"⧫\", \"⌧\", \"⍓\", \"⌘\",\n     \"✌\", \"👌\", \"👍\", \"👎\", \"☜\", \"☞\", \"☝\", \"☟\", \"✋\", \"☺\", \"😐\", \"☹\", \"💣\", \"☠\", \"⚐\", \"🏱\", \"✈\", \"☼\", \"💧\", \"❄\", \"🕆\", \"✞\", \"🕈\", \"✠\", \"✡\", \"☪\"],\n    \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\"))\n\n_METACHAR = {\"∶\": \":\", \"꞉\": \":\", \"ː\": \":\", \"︰\": \":\", \"﹕\": \":\", \"ǀ\": \"|\", \"∣\": \"|\",\n             \"‹\": \"<\", \"›\": \">\", \"〈\": \"<\", \"〉\": \">\", \"〈\": \"<\", \"〉\": \">\", \"⟨\": \"<\",\n             \"⟩\": \">\", \"﹤\": \"<\", \"﹥\": \">\", \"ᐸ\": \"<\", \"ᐳ\": \">\", \"˂\": \"<\", \"˃\": \">\",\n             \"⁄\": \"/\", \"∕\": \"/\", \"⧸\": \"/\", \"⧵\": \"\\\\\", \"∖\": \"\\\\\", \"ʼ\": \"'\", \"։\": \":\",\n             \"׃\": \":\", \"܃\": \":\", \"❰\": \"<\", \"❱\": \">\", \"❮\": \"<\", \"❯\": \">\", \"﹝\": \"[\",\n             \"﹞\": \"]\", \"❴\": \"{\", \"❵\": \"}\", \"⦃\": \"{\", \"⦄\": \"}\", \"〔\": \"[\", \"〕\": \"]\"}\n\n# Letters of other scripts that look like Latin letters (Unicode confusables,\n# the ones seen in attacks). Used only inside Latin words or Latin text.\n_HOMOGLYPH = {\n    # Cyrillic\n    \"а\": \"a\", \"в\": \"b\", \"е\": \"e\", \"ё\": \"e\", \"і\": \"i\", \"ї\": \"i\", \"ј\": \"j\", \"к\": \"k\", \"о\": \"o\", \"р\": \"p\", \"с\": \"c\",\n    \"у\": \"y\", \"х\": \"x\", \"ѕ\": \"s\", \"ԁ\": \"d\", \"ԛ\": \"q\", \"ԝ\": \"w\", \"һ\": \"h\", \"ӏ\": \"l\", \"ɡ\": \"g\",\n    \"А\": \"A\", \"В\": \"B\", \"Е\": \"E\", \"К\": \"K\", \"М\": \"M\", \"Н\": \"H\", \"О\": \"O\", \"Р\": \"P\", \"С\": \"C\", \"Т\": \"T\", \"Х\": \"X\",\n    \"Ү\": \"Y\", \"І\": \"I\", \"Ј\": \"J\", \"Ѕ\": \"S\", \"Ԁ\": \"D\", \"Ԛ\": \"Q\", \"Ԝ\": \"W\",\n    # Greek\n    \"α\": \"a\", \"ο\": \"o\", \"ν\": \"v\", \"ρ\": \"p\", \"ι\": \"i\", \"κ\": \"k\", \"υ\": \"u\", \"Α\": \"A\", \"Β\": \"B\", \"Ε\": \"E\", \"Ζ\": \"Z\",\n    \"Η\": \"H\", \"Ι\": \"I\", \"Κ\": \"K\", \"Μ\": \"M\", \"Ν\": \"N\", \"Ο\": \"O\", \"Ρ\": \"P\", \"Τ\": \"T\", \"Υ\": \"Y\", \"Χ\": \"X\",\n    # Others commonly used\n    \"ı\": \"i\", \"ȷ\": \"j\", \"ℓ\": \"l\", \"ᴦ\": \"r\", \"ꓲ\": \"I\", \"ꓳ\": \"O\", \"ꓑ\": \"P\", \"ꓢ\": \"S\", \"ꓔ\": \"T\", \"ꓮ\": \"A\", \"ꓐ\": \"B\",\n    \"ꓚ\": \"C\", \"ꓓ\": \"D\", \"ꓰ\": \"E\", \"ꓝ\": \"F\", \"ꓖ\": \"G\", \"ꓧ\": \"H\", \"ꓗ\": \"K\", \"ꓡ\": \"L\", \"ꓟ\": \"M\", \"ꓠ\": \"N\", \"ꓣ\": \"R\",\n    \"ꓴ\": \"U\", \"ꓦ\": \"V\", \"ꓪ\": \"W\", \"ꓫ\": \"X\", \"ꓬ\": \"Y\", \"ꓜ\": \"Z\",\n}\n\n\ndef _styled_latin(ch: str) -> str | None:\n    \"\"\"Base letter of a styled Latin letter (math, enclosed, small caps, ...).\"\"\"\n    try:\n        name = unicodedata.name(ch)\n    except ValueError:\n        return None\n    m = re.search(r\"SMALL CAPITAL ([A-Z])$\", name)\n    if m:\n        return m.group(1).lower()\n    m = re.search(r\"\\b(?:LATIN )?(CAPITAL|SMALL)(?: LETTER)? ([A-Z])$\", name)\n    if m and (\"LATIN\" in name or \"MATHEMATICAL\" in name or \"CIRCLED\" in name or \"SQUARED\" in name or \"PARENTHESIZED\" in name):\n        return m.group(2) if m.group(1) == \"CAPITAL\" else m.group(2).lower()\n    m = re.search(r\"LATIN LETTER SMALL CAPITAL ([A-Z])$\", name)\n    if m:\n        return m.group(1).lower()\n    m = re.search(r\"(?:DIGIT|NUMBER) (ZERO|ONE|TWO|THREE|FOUR|FIVE|SIX|SEVEN|EIGHT|NINE)$\", name)\n    if m and (\"CIRCLED\" in name or \"MATHEMATICAL\" in name or \"PARENTHESIZED\" in name or \"FULLWIDTH\" in name):\n        return str(\"ZERO ONE TWO THREE FOUR FIVE SIX SEVEN EIGHT NINE\".split().index(m.group(1)))\n    return None\n\n\ndef _fold_code(ch: str) -> tuple[str, str] | None:\n    \"\"\"(code, replacement) for a character some fold undoes, else None.\"\"\"\n    cp = ord(ch)\n    if 0xFF01 <= cp <= 0xFF5E:\n        return \"PIT-E-19\", chr(cp - 0xFEE0)\n    if 0x1D400 <= cp <= 0x1D7FF:\n        r = unicodedata.normalize(\"NFKC\", ch)\n        return (\"PIT-E-29\", r) if r != ch else None\n    if 0x2460 <= cp <= 0x24FF or 0x1F100 <= cp <= 0x1F1E5 or 0x3251 <= cp <= 0x32BF:\n        r = _styled_latin(ch) or unicodedata.normalize(\"NFKC\", ch)\n        return (\"PIT-E-12\", r.strip(\"()\")) if r != ch else None\n    if (0x1D00 <= cp <= 0x1DBF or 0x2070 <= cp <= 0x209F or 0xA730 <= cp <= 0xA7AF\n            or cp in (0xB2, 0xB3, 0xB9, 0x2071, 0x207F, 0x0274, 0x0280, 0x0262, 0x029C, 0x026A, 0x029F, 0x1D04, 0x0299, 0x1D20, 0x1D21, 0x1D22)):\n        try:\n            nm = unicodedata.name(ch)\n        except ValueError:\n            nm = \"\"\n        if any(w in nm for w in (\"SMALL CAPITAL\", \"SUBSCRIPT\", \"SUPERSCRIPT\", \"MODIFIER LETTER SMALL\")):\n            r = _styled_latin(ch) or unicodedata.normalize(\"NFKC\", ch)\n            return (\"PIT-E-40\", r) if r != ch and r.isascii() and r.isalnum() else None\n        return None\n    if 0x2800 <= cp <= 0x28FF:\n        return \"PIT-E-11\", _BRAILLE.get(cp - 0x2800, \"?\")\n    if 0x1F1E6 <= cp <= 0x1F1FF:\n        return \"PIT-E-34\", chr(ord(\"A\") + cp - 0x1F1E6)\n    if ch in _WINGDINGS:\n        return \"PIT-E-49\", _WINGDINGS[ch]\n    if ch in _METACHAR:\n        return \"PIT-E-28\", _METACHAR[ch]\n    return None\n\n\n_DESCRIPTIONS = {\n    \"PIT-E-19\": \"full-width character(s) folded to ordinary letters\",\n    \"PIT-E-29\": \"mathematical-style letter(s) folded to ordinary letters\",\n    \"PIT-E-12\": \"enclosed or bubble letter(s) folded to ordinary letters\",\n    \"PIT-E-40\": \"small-caps, superscript or subscript letter(s) folded\",\n    \"PIT-E-11\": \"Braille character(s) read as letters\",\n    \"PIT-E-34\": \"regional-indicator symbol(s) read as letters\",\n    \"PIT-E-49\": \"symbol-font character(s) (Wingdings) read as letters\",\n    \"PIT-E-28\": \"look-alike delimiter(s) (colons, brackets, bars, slashes) folded\",\n}\n\n\ndef folds(text: str, s: dict) -> tuple[str, list[Finding]]:\n    counts: dict[str, int] = {}\n    out: list[str] = []\n    i = 0\n    chars = list(text)\n    # Braille digits follow the number sign (⠼).\n    while i < len(chars):\n        ch = chars[i]\n        if ch == \"⠼\":\n            j = i + 1\n            digits = []\n            while j < len(chars) and 0x2800 <= ord(chars[j]) <= 0x28FF and _BRAILLE.get(ord(chars[j]) - 0x2800) in _BRAILLE_DIGITS:\n                digits.append(_BRAILLE_DIGITS[_BRAILLE[ord(chars[j]) - 0x2800]])\n                j += 1\n            if digits:\n                out.append(\"\".join(digits))\n                counts[\"PIT-E-11\"] = counts.get(\"PIT-E-11\", 0) + j - i\n                i = j\n                continue\n        if ch in (\"︎\", \"️\") and out and out[-1] in _WINGDINGS.values():\n            i += 1\n            continue\n        f = _fold_code(ch)\n        if f:\n            counts[f[0]] = counts.get(f[0], 0) + 1\n            out.append(f[1])\n        else:\n            out.append(ch)\n        i += 1\n    if not counts:\n        return text, []\n    res = \"\".join(out)\n    findings = []\n    for code, n in counts.items():\n        # Flags (pairs of regional indicators) and the odd symbol are ordinary:\n        # report a run only when it actually spells something.\n        if code in (\"PIT-E-34\", \"PIT-E-49\") and not _spells_text(text, res, code):\n            continue\n        findings.append(Finding(code, f\"{n} {_DESCRIPTIONS[code]}.\", short(text), short(res), count=n))\n    if not findings:\n        return text, []\n    reported = {f.code for f in findings}\n    if reported != set(counts):\n        # Undo only what was reported; leave ordinary flags and symbols alone.\n        res = \"\".join(_fold_code(ch)[1] if (_fold_code(ch) and _fold_code(ch)[0] in reported) else ch\n                      for ch in text if not (ch in (\"︎\", \"️\") and \"PIT-E-49\" in reported))\n    return res, findings\n\n\ndef _spells_text(original: str, folded: str, code: str) -> bool:\n    if code == \"PIT-E-34\":\n        runs = re.findall(r\"[\\U0001F1E6-\\U0001F1FF]{4,}\", original)\n        return any(plausible(\"\".join(chr(ord(\"a\") + ord(c) - 0x1F1E6) for c in r), min_known=0.6) for r in runs)\n    runs = re.findall(\"(?:[\" + \"\".join(re.escape(k) for k in _WINGDINGS) + r\"][︎️]?\\s?){4,}\", original)\n    return any(plausible(\"\".join(_WINGDINGS.get(c, \" \" if c == \" \" else \"\") for c in r)) for r in runs)\n\n\n_WORD = re.compile(r\"[^\\W\\d_]+\", re.UNICODE)\n\n\ndef _script(ch: str) -> str:\n    try:\n        name = unicodedata.name(ch)\n    except ValueError:\n        return \"?\"\n    return name.split(\" \", 1)[0]\n\n\ndef homoglyphs(text: str, s: dict) -> tuple[str, list[Finding]]:\n    letters = [ch for ch in text if ch.isalpha()]\n    latin_share = sum(_script(ch) == \"LATIN\" for ch in letters) / len(letters) if letters else 0\n    changed = 0\n    examples = []\n\n    def fix(m: re.Match) -> str:\n        nonlocal changed\n        w = m.group(0)\n        scripts = {_script(ch) for ch in w}\n        mixed = \"LATIN\" in scripts and len(scripts) > 1\n        # A whole word of look-alikes inside otherwise Latin text.\n        disguised = latin_share >= s[\"homoglyph_latin_share\"] and \"LATIN\" not in scripts and all(ch in _HOMOGLYPH for ch in w) and len(w) >= 2\n        if not (mixed or disguised):\n            return w\n        new = \"\".join(_HOMOGLYPH.get(ch, ch) if _script(ch) != \"LATIN\" else ch for ch in w)\n        if new != w:\n            changed += sum(a != b for a, b in zip(w, new))\n            if len(examples) < 3:\n                examples.append(f\"{w}→{new}\")\n        return new\n\n    res = _WORD.sub(fix, text)\n    if not changed:\n        return text, []\n    return res, [Finding(\"PIT-E-20\", f\"{changed} look-alike letter(s) from another script replaced inside Latin words ({', '.join(examples)}).\",\n                         short(text), short(res), count=changed)]\n\n\n# ---------------------------------------------------------------------------\n# E-45 upside down\n# ---------------------------------------------------------------------------\n_UPSIDE = {\"ɐ\": \"a\", \"q\": \"b\", \"ɔ\": \"c\", \"p\": \"d\", \"ǝ\": \"e\", \"ɟ\": \"f\", \"ƃ\": \"g\", \"ɥ\": \"h\", \"ᴉ\": \"i\", \"ı\": \"i\", \"ɾ\": \"j\",\n           \"ʞ\": \"k\", \"ן\": \"l\", \"l\": \"l\", \"ɯ\": \"m\", \"u\": \"n\", \"o\": \"o\", \"d\": \"p\", \"b\": \"q\", \"ɹ\": \"r\", \"s\": \"s\", \"ʇ\": \"t\",\n           \"n\": \"u\", \"ʌ\": \"v\", \"ʍ\": \"w\", \"x\": \"x\", \"ʎ\": \"y\", \"z\": \"z\", \"∀\": \"A\", \"ꓭ\": \"B\", \"Ɔ\": \"C\", \"ꓷ\": \"D\", \"Ǝ\": \"E\",\n           \"Ⅎ\": \"F\", \"⅁\": \"G\", \"H\": \"H\", \"I\": \"I\", \"ſ\": \"J\", \"ꓘ\": \"K\", \"˥\": \"L\", \"W\": \"M\", \"N\": \"N\", \"O\": \"O\", \"Ԁ\": \"P\",\n           \"Ꝺ\": \"Q\", \"ꓤ\": \"R\", \"S\": \"S\", \"⊥\": \"T\", \"∩\": \"U\", \"Λ\": \"V\", \"M\": \"W\", \"X\": \"X\", \"⅄\": \"Y\", \"Z\": \"Z\",\n           \"¡\": \"!\", \"¿\": \"?\", \"˙\": \".\", \"'\": \",\", \",\": \"'\", \" \": \" \"}\n_UPSIDE_MARK = set(\"ɐɔǝɟƃɥᴉɾʞɯɹʇʌʍʎ∀ꓭƆꓷƎℲ⅁ſꓘ˥ԀꝹꓤ⊥∩Λ⅄¡¿˙ן\")\n\n\ndef upside_down(text: str, s: dict) -> tuple[str, list[Finding]]:\n    if sum(ch in _UPSIDE_MARK for ch in text) < s[\"upside_down_min\"]:\n        return text, []\n    found = []\n\n    def flip(m: re.Match) -> str:\n        run = m.group(0)\n        if sum(ch in _UPSIDE_MARK for ch in run) < s[\"upside_down_min\"]:\n            return run\n        new = \"\".join(_UPSIDE.get(ch, ch) for ch in reversed(run))\n        found.append((run, new))\n        return new\n\n    res = re.sub(\"[\" + re.escape(\"\".join(_UPSIDE)) + r\"\\s]{4,}\", flip, text)\n    if not found:\n        return text, []\n    return res, [Finding(\"PIT-E-45\", \"Upside-down text turned the right way up.\", short(found[0][0]), short(found[0][1]), count=len(found))]\n\n\n# ---------------------------------------------------------------------------\n# E-37 spaces/whitespace, E-38 splats, E-47 vertical, E-13 case\n# ---------------------------------------------------------------------------\n_EXOTIC_SPACE = re.compile(\"[ -  　   \\u0085]\")\n\n\ndef whitespace(text: str, s: dict) -> tuple[str, list[Finding]]:\n    findings = []\n    n_exotic = len(_EXOTIC_SPACE.findall(text))\n    res = _EXOTIC_SPACE.sub(\" \", text).replace(\" \", \" \").replace(\" \", \" \")\n    spaced = []\n\n    def join(m: re.Match) -> str:\n        joined = m.group(0).replace(\" \", \"\").replace(\"\\t\", \"\")\n        if plausible(joined):\n            spaced.append((m.group(0), joined))\n            return joined\n        return m.group(0)\n\n    res = re.sub(r\"(?<!\\S)(?:[^\\W_][ \\t]{1,2}){%d,}[^\\W_](?!\\S)\" % (s[\"spaced_letters_min\"] - 1), join, res)\n    if spaced:\n        findings.append(Finding(\"PIT-E-37\", \"Letters spread out with spaces were joined back into words.\", short(spaced[0][0]), short(spaced[0][1]), count=len(spaced)))\n    elif n_exotic >= s[\"exotic_space_min\"]:\n        findings.append(Finding(\"PIT-E-37\", f\"{n_exotic} unusual space character(s) replaced with ordinary spaces.\", short(text), short(res), count=n_exotic))\n    return res, findings\n\n\ndef splats(text: str, s: dict) -> tuple[str, list[Finding]]:\n    found = []\n\n    def join(m: re.Match) -> str:\n        sep = m.group(1)\n        parts = m.group(0).split(sep)\n        joined = \"\".join(parts)\n        if all(len(p) <= 2 for p in parts) and plausible(joined):\n            found.append((m.group(0), joined))\n            return joined\n        return m.group(0)\n\n    res = re.sub(r\"\\b\\w{1,2}([*._\\-|~+^#=/\\\\])(?:\\w{1,2}\\1){%d,}\\w{1,2}\\b\" % (s[\"splat_min_parts\"] - 2), join, text)\n    if not found:\n        return text, []\n    return res, [Finding(\"PIT-E-38\", \"Words broken up with symbols between the letters were joined back.\", short(found[0][0]), short(found[0][1]), count=len(found))]\n\n\ndef vertical(text: str, s: dict) -> tuple[str, list[Finding]]:\n    found = []\n    vforms = sum(1 for ch in text if 0xFE10 <= ord(ch) <= 0xFE19 or 0xFE30 <= ord(ch) <= 0xFE4F)\n    res = \"\".join(unicodedata.normalize(\"NFKC\", ch) if (0xFE10 <= ord(ch) <= 0xFE19 or 0xFE30 <= ord(ch) <= 0xFE4F) else ch for ch in text)\n\n    def join(m: re.Match) -> str:\n        lines = [ln.strip() for ln in m.group(0).split(\"\\n\")]\n        joined = \"\".join(ln if ln else \" \" for ln in lines)\n        if plausible(joined):\n            found.append((m.group(0), joined))\n            return joined + \"\\n\"\n        return m.group(0)\n\n    res = re.sub(r\"(?m)(?:^[ \\t]*\\S?[ \\t]*\\n){%d,}\" % s[\"vertical_min_lines\"], join, res + \"\\n\")[:-1]\n    if not found and not vforms:\n        return text, []\n    excerpt = found[0][0] if found else text\n    return res, [Finding(\"PIT-E-47\", \"Text written one letter per line (vertical) was read across.\", short(excerpt), short(found[0][1] if found else res), count=len(found) or vforms)]\n\n\ndef case_changes(text: str, s: dict) -> tuple[str, list[Finding]]:\n    words = []\n\n    def fix(m: re.Match) -> str:\n        w = m.group(0)\n        if len(w) < 3 or w.isupper() or w.islower():\n            return w\n        flips = sum(1 for a, b in zip(w, w[1:]) if a.isupper() != b.isupper())\n        # Only real words: a token mixing letters with digits or + / = is an\n        # encoding or an identifier, and decoders need its case intact.\n        if flips / (len(w) - 1) >= s[\"case_flip_ratio\"] and (w.lower() in WORDS or plausible(w.lower(), min_known=0.6)):\n            words.append(w)\n            return w.lower()\n        return w\n\n    res = re.sub(r\"(?<![\\w+/=])[^\\W\\d_]+(?![\\w+/=])\", fix, text)\n    if len(words) < s[\"case_words_min\"]:\n        return text, []\n    return res, [Finding(\"PIT-E-13\", f\"{len(words)} word(s) with alternating capital letters read in ordinary case.\", short(\" \".join(words)), short(res), count=len(words))]\n\n\n# Order matters: escapes and controls first, then what hides inside words,\n# then character folds, then layout tricks.\nSTEPS = (ansi, bidi, invisible, overlay, zalgo, folds, upside_down, homoglyphs, whitespace, splats, vertical, case_changes)\n\n\ndef normalize(text: str, s: dict) -> tuple[str, list[Finding]]:\n    findings: list[Finding] = []\n    for step in STEPS:\n        text, f = step(text, s)\n        findings.extend(f)\n    return text, findings\n", "vid/input_layer/decoders.py": "\"\"\"Decoders: the 17 decoder codes of the basic layer (docs/REFERENCE.md Sec 3,\nSec 15). Decoding is repeated until text is reached or a fixed depth is hit\n(`input_layer.max_depth` in config); the repetition is E-57.\n\nA decoding counts only when what comes out reads like language\n(textscore.plausible) and reads better than what went in. That keeps\nidentifiers, hashes, keys and product numbers out (Sec 3, COST).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport base64\nimport binascii\nimport bz2\nimport html\nimport re\nimport urllib.parse\nimport zlib\nfrom typing import Callable\n\nfrom vid.input_layer.textscore import known_share, plausible, printable_text, score, segmented_share\n\ntry:  # lzma is optional in some Python builds (e.g. in the browser)\n    import lzma\nexcept ImportError:  # pragma: no cover\n    lzma = None\n\nDecoded = tuple[str, str]   # (decoded text, what was decoded: the excerpt)\n\n\n# ---------------------------------------------------------------------------\n# helpers\n# ---------------------------------------------------------------------------\ndef _bytes_to_text(b: bytes) -> str | None:\n    return _decompress(b) or printable_text(b)\n\n\ndef _decompress(b: bytes) -> str | None:\n    for magic, fn in ((b\"\\x1f\\x8b\", lambda x: zlib.decompress(x, 16 + zlib.MAX_WBITS)),\n                      (b\"BZh\", bz2.decompress),\n                      (b\"\\xfd7zXZ\", lzma.decompress if lzma else None)):\n        if fn and b.startswith(magic):\n            try:\n                return printable_text(fn(b))\n            except Exception:\n                return None\n    if len(b) > 2 and b[0] == 0x78 and b[1] in (0x01, 0x5E, 0x9C, 0xDA):\n        try:\n            return printable_text(zlib.decompress(b))\n        except zlib.error:\n            return None\n    return None\n\n\ndef _is_compressed(b: bytes) -> bool:\n    return b.startswith((b\"\\x1f\\x8b\", b\"BZh\", b\"\\xfd7zXZ\")) or (len(b) > 2 and b[0] == 0x78 and b[1] in (0x01, 0x5E, 0x9C, 0xDA))\n\n\ndef _better(decoded: str, original: str) -> bool:\n    return plausible(decoded) and score(decoded) > score(original) + 0.15\n\n\n# ---------------------------------------------------------------------------\n# E-07 Base64, E-55 other bases, E-58 compression\n# ---------------------------------------------------------------------------\n_B64 = re.compile(r\"(?<![A-Za-z0-9+/=_-])[A-Za-z0-9+/_-]{12,}={0,2}(?![A-Za-z0-9+/=_-])\")\n_B32 = re.compile(r\"(?<![A-Z2-7=])[A-Z2-7]{16,}={0,6}(?![A-Z2-7=])\")\n_A85 = re.compile(r\"<~(.+?)~>\", re.S)\n_B58 = re.compile(r\"(?<![1-9A-HJ-NP-Za-km-z])[1-9A-HJ-NP-Za-km-z]{12,}(?![1-9A-HJ-NP-Za-km-z])\")\n_B58_ALPHA = \"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz\"\n\n\ndef base64_dec(text: str) -> list[tuple[str, str, str]]:\n    \"\"\"[(code, excerpt, decoded)] for Base64 (E-07) and compressed payloads (E-58).\"\"\"\n    out = []\n    for m in _B64.finditer(text):\n        tok = m.group(0)\n        try:\n            raw = base64.b64decode(tok + \"=\" * (-len(tok) % 4), altchars=b\"-_\" if (\"-\" in tok or \"_\" in tok) else None, validate=True)\n        except (binascii.Error, ValueError):\n            continue\n        if _is_compressed(raw):\n            s = _decompress(raw)\n            if s:\n                out.append((\"PIT-E-58\", tok, s))\n            continue\n        s = printable_text(raw)\n        if s and (plausible(s) or _B64.search(s) or _looks_encoded(s)):\n            out.append((\"PIT-E-07\", tok, s))\n    return out\n\n\ndef _looks_encoded(s: str) -> bool:\n    \"\"\"Decoded output that is itself another encoding (for layered payloads).\"\"\"\n    s = s.strip()\n    return bool(re.fullmatch(r\"(?:%[0-9A-Fa-f]{2})+.*|[0-9A-Fa-f\\s]{16,}|[01\\s]{16,}|[.\\-/ ]{8,}|&#?\\w+;.*|<~.+~>\", s, re.S))\n\n\ndef other_bases(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in _B32.finditer(text):\n        tok = m.group(0)\n        try:\n            raw = base64.b32decode(tok + \"=\" * (-len(tok) % 8))\n        except (binascii.Error, ValueError):\n            continue\n        s = _bytes_to_text(raw)\n        if s and (plausible(s) or _looks_encoded(s)):\n            out.append((\"PIT-E-55\", tok, s))\n    for m in _A85.finditer(text):\n        try:\n            raw = base64.a85decode(m.group(0), adobe=True)\n        except (ValueError, binascii.Error):\n            continue\n        s = _bytes_to_text(raw)\n        if s:\n            out.append((\"PIT-E-55\", m.group(0), s))\n    for m in _B58.finditer(text):\n        tok = m.group(0)\n        n = 0\n        for c in tok:\n            n = n * 58 + _B58_ALPHA.index(c)\n        raw = n.to_bytes((n.bit_length() + 7) // 8, \"big\")\n        s = printable_text(raw)\n        if s and plausible(s) and not _B64_plausible(tok):\n            out.append((\"PIT-E-55\", tok, s))\n    return out\n\n\ndef _B64_plausible(tok: str) -> bool:\n    try:\n        s = printable_text(base64.b64decode(tok + \"=\" * (-len(tok) % 4), validate=True))\n    except (binascii.Error, ValueError):\n        return False\n    return bool(s and plausible(s))\n\n\n# ---------------------------------------------------------------------------\n# E-08 binary, E-21 hex, E-56 numeric code points, E-01 A1Z26\n# ---------------------------------------------------------------------------\n_BIN = re.compile(r\"(?<![01])(?:[01]{7,8}[\\s,]*){4,}(?![01])\")\n_HEX = re.compile(r\"(?:(?:\\\\x|0x)?[0-9A-Fa-f]{2}[\\s,:]*){6,}\")\n_CODEPOINTS = re.compile(r\"(?:(?:U\\+|\\\\u)[0-9A-Fa-f]{2,6};?[\\s,]*){4,}\")\n_NUMBERS = re.compile(r\"(?<![\\d.])(?:\\d{1,3}[\\s,\\-]+){3,}\\d{1,3}(?![\\d.])\")\n\n\ndef binary(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in _BIN.finditer(text):\n        groups = re.findall(r\"[01]{7,8}\", m.group(0))\n        s = printable_text(bytes(int(g, 2) for g in groups))\n        if s and (plausible(s) or _looks_encoded(s)):\n            out.append((\"PIT-E-08\", m.group(0).strip(), s))\n    return out\n\n\ndef hexadecimal(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in _HEX.finditer(text):\n        digits = re.sub(r\"\\\\x|0x|[\\s,:]\", \"\", m.group(0))\n        if len(digits) % 2 or len(digits) < 12:\n            continue\n        try:\n            raw = bytes.fromhex(digits)\n        except ValueError:\n            continue\n        s = _bytes_to_text(raw)\n        if s and (plausible(s) or _looks_encoded(s)):\n            out.append((\"PIT-E-58\" if _is_compressed(raw) else \"PIT-E-21\", m.group(0).strip(), s))\n    return out\n\n\ndef codepoints(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in _CODEPOINTS.finditer(text):\n        tok = m.group(0)\n        if not re.search(r\"U\\+|\\\\u\", tok):\n            continue  # &#...; belongs to HTML entities (E-22)\n        vals = []\n        for v in re.findall(r\"(?:U\\+|\\\\u)([0-9A-Fa-f]{2,6})\", tok):\n            try:\n                vals.append(int(v, 16))\n            except ValueError:\n                pass\n        try:\n            s = \"\".join(chr(v) for v in vals)\n        except (ValueError, OverflowError):\n            continue\n        if plausible(s):\n            out.append((\"PIT-E-56\", tok.strip(), s))\n    for m in _NUMBERS.finditer(text):\n        vals = [int(v) for v in re.findall(r\"\\d+\", m.group(0))]\n        if all(32 <= v <= 126 for v in vals):\n            s = \"\".join(map(chr, vals))\n            if plausible(s):\n                out.append((\"PIT-E-56\", m.group(0), s))\n        elif all(1 <= v <= 26 for v in vals):\n            continue  # A1Z26 handles these\n    return out\n\n\ndef a1z26(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in re.finditer(r\"(?<![\\d.])(?:(?:[1-9]|1\\d|2[0-6])(?:[\\s,\\-]+|\\s*/\\s*)){3,}(?:[1-9]|1\\d|2[0-6])(?![\\d.])\", text):\n        words = re.split(r\"\\s*/\\s*|\\s{2,}\", m.group(0).strip())\n        s = \" \".join(\"\".join(chr(96 + int(v)) for v in re.findall(r\"\\d+\", w)) for w in words)\n        if plausible(s):\n            out.append((\"PIT-E-01\", m.group(0).strip(), s))\n    return out\n\n\n# ---------------------------------------------------------------------------\n# E-30 Morse, E-31 NATO, E-06 Baconian, E-44 tap code\n# ---------------------------------------------------------------------------\n_MORSE = dict(zip(\".- -... -.-. -.. . ..-. --. .... .. .--- -.- .-.. -- -. --- .--. --.- .-. ... - ..- ...- .-- -..- -.-- --.. \"\n                  \"----- .---- ..--- ...-- ....- ..... -.... --... ---.. ----.\".split(), \"abcdefghijklmnopqrstuvwxyz0123456789\"))\n_NATO = {w: w[0] for w in \"alfa alpha bravo charlie delta echo foxtrot golf hotel india juliett juliet kilo lima mike november \"\n         \"oscar papa quebec romeo sierra tango uniform victor whiskey whisky xray x-ray yankee zulu\".split()}\n\n\ndef morse(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in re.finditer(r\"(?:[.\\-·•−–_]{1,6}(?:\\s+|\\s*/\\s*|\\|)){4,}[.\\-·•−–_]{1,6}\", text):\n        tok = m.group(0).translate(str.maketrans(\"·•−–_\", \"..---\"))\n        words = re.split(r\"\\s*/\\s*|\\s{3,}|\\|\", tok.strip())\n        s = \" \".join(\"\".join(_MORSE.get(c, \"?\") for c in w.split()) for w in words)\n        if \"?\" not in s and plausible(s):\n            out.append((\"PIT-E-30\", m.group(0).strip(), s))\n    return out\n\n\ndef nato(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    pat = r\"\\b(?:(?:\" + \"|\".join(sorted(_NATO, key=len, reverse=True)) + r\")[\\s,/-]+){3,}(?:\" + \"|\".join(sorted(_NATO, key=len, reverse=True)) + r\")\\b\"\n    for m in re.finditer(pat, text, re.I):\n        groups = re.split(r\"\\s*/\\s*|\\s{2,}\", m.group(0))\n        s = \" \".join(\"\".join(_NATO[w.lower()] for w in re.findall(r\"[A-Za-z-]+\", g) if w.lower() in _NATO) for g in groups)\n        if plausible(s):\n            out.append((\"PIT-E-31\", m.group(0), s))\n    return out\n\n\ndef _bacon_table(full: bool) -> dict[str, str]:\n    letters = \"abcdefghijklmnopqrstuvwxyz\" if full else \"abcdefghiklmnopqrstuwxyz\"\n    t = {format(i, \"05b\").replace(\"0\", \"a\").replace(\"1\", \"b\"): ch for i, ch in enumerate(letters)}\n    return t\n\n\ndef baconian(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in re.finditer(r\"(?:[ABab]{5}\\s*){4,}\", text):\n        tok = re.sub(r\"\\s\", \"\", m.group(0)).lower()\n        if len(tok) % 5:\n            continue\n        best = None\n        for full in (False, True):\n            table = _bacon_table(full)\n            cand = \"\".join(table.get(tok[i:i + 5], \"?\") for i in range(0, len(tok), 5))\n            if \"?\" not in cand and plausible(cand) and (best is None or segmented_share(cand) > segmented_share(best)):\n                best = cand\n        if best:\n            out.append((\"PIT-E-06\", m.group(0).strip(), best))\n    return out\n\n\n_POLYBIUS = \"abcdefghiklmnopqrstuvwxyz\"   # 5x5, C stands for K\n\n\ndef tap_code(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in re.finditer(r\"(?:\\.{1,5} \\.{1,5}(?:\\s{2,}|\\s*/\\s*|$|\\s(?=\\.)))(?:\\.{1,5} \\.{1,5}(?:\\s{2,}|\\s*/\\s*|\\s(?=\\.)|$)){3,}\", text):\n        pairs = re.findall(r\"(\\.{1,5}) (\\.{1,5})\", m.group(0))\n        s = \"\".join(_POLYBIUS[(len(a) - 1) * 5 + len(b) - 1] for a, b in pairs)\n        if plausible(s):\n            out.append((\"PIT-E-44\", m.group(0).strip(), s))\n    for m in re.finditer(r\"(?:\\b[1-5][1-5]\\b[\\s,]*){4,}\", text):\n        pairs = re.findall(r\"\\b([1-5])([1-5])\\b\", m.group(0))\n        s = \"\".join(_POLYBIUS[(int(a) - 1) * 5 + int(b) - 1] for a, b in pairs)\n        if plausible(s):\n            out.append((\"PIT-E-44\", m.group(0).strip(), s))\n    return out\n\n\n# ---------------------------------------------------------------------------\n# E-46 URL encoding, E-22 HTML entities, E-62 legacy charsets\n# ---------------------------------------------------------------------------\ndef url_encoding(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in re.finditer(r\"(?:[^\\s%]*%[0-9A-Fa-f]{2})+[^\\s%]*\", text):\n        tok = m.group(0)\n        escapes = re.findall(r\"%([0-9A-Fa-f]{2})\", tok)\n        # Escaping ordinary letters and digits is never needed: that is concealment.\n        unneeded = sum(1 for e in escapes if chr(int(e, 16)).isalnum())\n        if unneeded < 3:\n            continue\n        s = urllib.parse.unquote(tok)\n        if s != tok and (plausible(s) or _looks_encoded(s)):\n            out.append((\"PIT-E-46\", tok, s))\n    return out\n\n\ndef html_entities(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for m in re.finditer(r\"(?:[^\\s&]*&(?:#\\d{2,7}|#x[0-9A-Fa-f]{2,6}|[A-Za-z]{2,10});)+[^\\s&]*\", text):\n        tok = m.group(0)\n        numeric_letters = sum(1 for v in re.findall(r\"&#(x?)([0-9A-Fa-f]+);\", tok)\n                              if chr(int(v[1], 16 if v[0] else 10)).isalnum()) if re.search(r\"&#\", tok) else 0\n        if numeric_letters < 3:\n            continue\n        s = html.unescape(tok)\n        if s != tok and (plausible(s) or _looks_encoded(s)):\n            out.append((\"PIT-E-22\", tok, s))\n    return out\n\n\n_MOJIBAKE = re.compile(r\"[ÃÂÐÑÄÅ][\\x80-\\xbf\\u0152-\\u2122]\")\n\n\ndef legacy_charset(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    # UTF-7: decode the whole string at once (\"+AO8-\" runs are one char each).\n    if re.search(r\"\\+[A-Za-z0-9+/]{2,}-\", text) and text.isascii():\n        try:\n            s = text.encode(\"ascii\").decode(\"utf-7\")\n        except UnicodeError:\n            s = None\n        if s and s != text and any(not ch.isascii() for ch in s) and plausible(s):\n            out.append((\"PIT-E-62\", text, s))\n    # Text decoded with the wrong charset (UTF-8 bytes read as Latin-1/CP1252)\n    if _MOJIBAKE.search(text):\n        for enc in (\"cp1252\", \"latin-1\"):\n            try:\n                s = text.encode(enc).decode(\"utf-8\")\n            except UnicodeError:\n                continue\n            if s != text:\n                out.append((\"PIT-E-62\", text, s))\n                break\n    # Quoted-printable runs\n    for m in re.finditer(r\"(?:=[0-9A-F]{2}){4,}\", text):\n        try:\n            s = printable_text(binascii.a2b_qp(m.group(0)))\n        except binascii.Error:\n            continue\n        if s and plausible(s):\n            out.append((\"PIT-E-62\", m.group(0), s))\n    return out\n\n\n# ---------------------------------------------------------------------------\n# E-36 reverse, E-33 rail fence (by search)\n# ---------------------------------------------------------------------------\ndef reverse(text: str) -> list[tuple[str, str, str]]:\n    out = []\n    for line in text.splitlines():\n        line = line.strip()\n        if len(line) < 8 or plausible(line):\n            continue\n        whole = line[::-1]\n        words = \" \".join(w[::-1] for w in line.split())\n        for cand in (whole, words):\n            if _better(cand, line):\n                out.append((\"PIT-E-36\", line, cand))\n                break\n    return out\n\n\ndef _rail_decrypt(cipher: str, rails: int) -> str:\n    n = len(cipher)\n    pattern = []\n    r, step = 0, 1\n    for _ in range(n):\n        pattern.append(r)\n        if rails > 1:\n            if r == 0:\n                step = 1\n            elif r == rails - 1:\n                step = -1\n            r += step\n    order = sorted(range(n), key=lambda i: (pattern[i], i))\n    res = [\"\"] * n\n    for ch, idx in zip(cipher, order):\n        res[idx] = ch\n    return \"\".join(res)\n\n\ndef rail_fence(text: str, max_rails: int = 8) -> list[tuple[str, str, str]]:\n    # A transposition cipher only permutes letters, so letter-pair structure\n    # cannot tell a solution from the scramble: require real words instead.\n    out = []\n    for line in text.splitlines():\n        line = line.strip()\n        if len(line) < 12 or \" \" in line.strip() or segmented_share(line) >= 0.6:\n            continue\n        base = segmented_share(line)\n        best = None\n        for rails in range(2, min(max_rails, len(line) // 2) + 1):\n            cand = _rail_decrypt(line, rails)\n            share = segmented_share(cand)\n            if share >= 0.7 and share > base + 0.3 and (best is None or share > best[0]):\n                best = (share, cand)\n        if best:\n            out.append((\"PIT-E-33\", line, best[1]))\n    return out\n\n\n# The decoders, in the order they are tried at each depth.\nDECODERS: tuple[Callable[[str], list[tuple[str, str, str]]], ...] = (\n    base64_dec, other_bases, hexadecimal, binary, codepoints, url_encoding, html_entities,\n    legacy_charset, morse, nato, baconian, tap_code, a1z26, reverse, rail_fence,\n)\n\n\ndef decode_once(text: str) -> list[tuple[str, str, str]]:\n    seen = set()\n    out = []\n    for fn in DECODERS:\n        for code, excerpt, decoded in fn(text):\n            key = (excerpt, decoded)\n            if key in seen or decoded == excerpt:\n                continue\n            seen.add(key)\n            out.append((code, excerpt, decoded))\n    return out\n", "vid/input_layer/structure.py": "\"\"\"Flattening of structure (docs/REFERENCE.md Sec 3): content inside JSON,\nXML, Markdown or a graph of nodes is taken out of its wrapper and read as\nplain text. Codes E-18, E-25, E-27, E-50.\"\"\"\n\nfrom __future__ import annotations\n\nimport html\nimport json\nimport re\n\nfrom vid.input_layer.types import Finding, short\n\n\ndef _strings(value, out: list[str]) -> None:\n    if isinstance(value, str):\n        out.append(value)\n    elif isinstance(value, dict):\n        for k, v in value.items():\n            if isinstance(k, str) and len(k) > 24:\n                out.append(k)          # long keys can carry text too\n            _strings(v, out)\n    elif isinstance(value, list):\n        for v in value:\n            _strings(v, out)\n\n\ndef _json_blocks(text: str):\n    \"\"\"Top-level JSON objects/arrays inside text, as (span, value).\"\"\"\n    i = 0\n    while i < len(text):\n        if text[i] in \"{[\":\n            try:\n                value, end = json.JSONDecoder().raw_decode(text, i)\n            except ValueError:\n                i += 1\n                continue\n            if isinstance(value, (dict, list)) and end - i >= 8:\n                yield (i, end), value\n                i = end\n                continue\n        i += 1\n\n\ndef json_flat(text: str) -> tuple[str, list[Finding]]:\n    pieces, spans = [], []\n    for span, value in _json_blocks(text):\n        strings: list[str] = []\n        _strings(value, strings)\n        if any(len(s) >= 3 for s in strings):\n            spans.append((span, \"\\n\".join(strings)))\n            pieces.extend(strings)\n    if not spans:\n        return text, []\n    out, last = [], 0\n    for (a, b), flat in spans:\n        out.append(text[last:a])\n        out.append(flat)\n        last = b\n    out.append(text[last:])\n    res = \"\".join(out)\n    return res, [Finding(\"PIT-E-25\", f\"Text inside JSON taken out of its wrapper ({len(pieces)} string(s)).\",\n                         short(text[spans[0][0][0]:spans[0][0][1]]), short(\" | \".join(pieces)), count=len(pieces))]\n\n\n_XML_HINT = re.compile(r\"<\\?xml|<([A-Za-z_][\\w.\\-:]*)(?:\\s[^<>]*)?>.*?</\\1\\s*>\", re.S)\n_TAG = re.compile(r\"<[^<>]+>\")\n\n\ndef xml_flat(text: str) -> tuple[str, list[Finding]]:\n    if not _XML_HINT.search(text):\n        return text, []\n    hidden = []\n    for m in re.finditer(r\"<!--(.*?)-->\", text, re.S):\n        hidden.append(m.group(1).strip())\n    for m in re.finditer(r\"<!\\[CDATA\\[(.*?)\\]\\]>\", text, re.S):\n        hidden.append(m.group(1).strip())\n    for m in re.finditer(r\"\\s[\\w:\\-]+\\s*=\\s*(\\\"[^\\\"]*\\\"|'[^']*')\", text):\n        v = m.group(1)[1:-1].strip()\n        if len(v) >= 12 and \" \" in v:\n            hidden.append(v)\n    body = re.sub(r\"<!--.*?-->|<!\\[CDATA\\[.*?\\]\\]>\", \" \", text, flags=re.S)\n    body = html.unescape(_TAG.sub(\" \", body))\n    body = re.sub(r\"[ \\t]+\", \" \", body).strip()\n    res = \"\\n\".join([body, *hidden]).strip()\n    detail = \"Text inside XML/HTML tags taken out of its wrapper\"\n    if hidden:\n        detail += f\"; {len(hidden)} comment(s), CDATA or attribute text included\"\n    return res, [Finding(\"PIT-E-50\", detail + \".\", short(text), short(res), count=max(1, len(hidden)))]\n\n\ndef markdown_flat(text: str) -> tuple[str, list[Finding]]:\n    hidden = []\n    hidden += [m.group(1).strip() for m in re.finditer(r\"<!--(.*?)-->\", text, re.S)]\n    hidden += [m.group(1).strip() for m in re.finditer(r\"!\\[([^\\]]+)\\]\\([^)]*\\)\", text)]          # image alt text\n    hidden += [m.group(1) for m in re.finditer(r\"\\]\\([^)\\s]*\\s+\\\"([^\\\"]+)\\\"\\)\", text)]            # link / image titles\n    hidden += [m.group(2).strip() for m in re.finditer(r\"(?m)^\\s*\\[([^\\]^]+)\\]:\\s*\\S+(?:\\s+[\\\"'(](.+?)[\\\"')])?\\s*$\", text) if m.group(2)]\n    hidden += [m.group(1).strip() for m in re.finditer(r\"(?m)^\\s*\\[\\^[^\\]]+\\]:\\s*(.+)$\", text)]   # footnotes\n    hidden += [m.group(1).strip() for m in re.finditer(r\"\\[[^\\]]*\\]:\\s*#\\s*\\((.*?)\\)\", text)]    # [//]: # (comment)\n    md_like = re.search(r\"(?m)^#{1,6}\\s|\\*\\*.+?\\*\\*|\\[[^\\]]+\\]\\([^)]+\\)|^```|^\\s*[-*]\\s\", text)\n    if not hidden or not (md_like or \"<!--\" in text or \"![\" in text or re.search(r\"(?m)^\\s*\\[[^\\]]+\\]:\", text)):\n        return text, []\n    body = re.sub(r\"<!--.*?-->\", \" \", text, flags=re.S)\n    body = re.sub(r\"!\\[[^\\]]*\\]\\([^)]*\\)\", \" \", body)\n    body = re.sub(r\"\\[([^\\]]+)\\]\\([^)]*\\)\", r\"\\1\", body)\n    body = re.sub(r\"(?m)^\\s*\\[[^\\]]+\\]:.*$\", \"\", body)\n    body = re.sub(r\"[*_`#>]+\", \"\", body).strip()\n    res = \"\\n\".join([body, *hidden]).strip()\n    return res, [Finding(\"PIT-E-27\", f\"Markdown read as plain text; {len(hidden)} hidden part(s) (comments, alt text, titles, references) included.\",\n                         short(text), short(\" | \".join(hidden)), count=len(hidden))]\n\n\ndef graph_flat(text: str) -> tuple[str, list[Finding]]:\n    labels = []\n    if re.search(r\"\\b(?:di)?graph\\s*\\w*\\s*\\{\", text) and re.search(r\"->|--\", text):          # Graphviz DOT\n        labels += re.findall(r\"label\\s*=\\s*\\\"((?:[^\\\"\\\\]|\\\\.)*)\\\"\", text)\n        labels += [a for a in re.findall(r\"\\\"((?:[^\\\"\\\\]|\\\\.){3,})\\\"\\s*(?:->|--|\\[|;)\", text) if a not in labels]\n    if re.search(r\"(?m)^\\s*(?:graph|flowchart)\\s+(?:TD|TB|BT|RL|LR)\\b\", text):              # Mermaid\n        labels += re.findall(r\"\\w+\\s*[\\[\\(\\{>]{1,2}\\\"?([^\\]\\)\\}\\\"]+?)\\\"?[\\]\\)\\}]{1,2}\", text)\n        labels += re.findall(r\"--\\s*\\\"?([^\\-\\\">|]+?)\\\"?\\s*-->\", text)\n        labels += re.findall(r\"-->\\|([^|]+)\\|\", text)\n    try:\n        data = json.loads(text)\n    except ValueError:\n        data = None\n    if isinstance(data, dict) and (\"nodes\" in data or \"edges\" in data):\n        for key in (\"nodes\", \"edges\", \"links\"):\n            for item in data.get(key, []) or []:\n                if isinstance(item, dict):\n                    labels += [str(v) for k, v in item.items() if k in (\"label\", \"text\", \"name\", \"title\", \"content\", \"data\") and isinstance(v, (str, int))]\n    labels = [l.strip() for l in labels if l and l.strip()]\n    if not labels:\n        return text, []\n    res = \"\\n\".join(labels)\n    return res, [Finding(\"PIT-E-18\", f\"Text from {len(labels)} graph node(s) and edge(s) read in order.\", short(text), short(\" | \".join(labels)), count=len(labels))]\n\n\ndef flatten(text: str) -> tuple[str, list[Finding]]:\n    findings: list[Finding] = []\n    for fn in (graph_flat, json_flat, xml_flat, markdown_flat):\n        new, f = fn(text)\n        if f:\n            findings.extend(f)\n            text = new\n    return text, findings\n", "vid/input_layer/control_tokens.py": "\"\"\"Removal of the model's control tokens and end sequences, and their near\nneighbours, from any input that is not the system's own\n(docs/REFERENCE.md Sec 3). Codes T-07 (end sequences) and T-48 (special\ntokens).\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom vid.input_layer.types import Finding, short\n\n_END_NAMES = r\"(?:im_end|endoftext|end_of_text|eot_id|eom_id|end|eos|stop|return|endofprompt|end_of_turn|im_sep)\"\n# Pipe tokens in any spacing or case: <|im_end|>, < | IM_END | >, <|im_end>, <im_end|>\n_PIPE_TOKEN = re.compile(r\"<\\s*\\|\\s*([A-Za-z][\\w\\-]{1,40})\\s*\\|?\\s*>|<\\s*([A-Za-z][\\w\\-]{1,40})\\s*\\|\\s*>\")\n_OTHER_SPECIAL = re.compile(\n    r\"\\[\\s*/?\\s*INST\\s*\\]|<<\\s*/?\\s*SYS\\s*>>|<\\s*/?\\s*(?:start_of_turn|end_of_turn)\\s*>|<\\s*(?:bos|eos)\\s*>\"\n    r\"|<\\s*/?\\s*(?:system|assistant|tool_call|tool_response|im_start|im_end)\\s*>\"\n    r\"|<\\s*reserved_special_token_\\d+\\s*>\",\n    re.I)\n# Legacy turn markers that end the user's turn (\"\\n\\nHuman:\", \"\\n\\nAssistant:\")\n_TURN = re.compile(r\"(?:^|\\n)\\s*\\n\\s*(Human|Assistant)\\s*:\", re.I)\n_EOS_S = re.compile(r\"</s>\")\n\n\ndef remove(text: str) -> tuple[str, list[Finding]]:\n    ends, specials = [], []\n\n    def pipe(m: re.Match) -> str:\n        name = (m.group(1) or m.group(2)).lower()\n        (ends if re.fullmatch(_END_NAMES, name) else specials).append(m.group(0))\n        return \" \"\n\n    out = _PIPE_TOKEN.sub(pipe, text)\n\n    def other(m: re.Match) -> str:\n        tok = re.sub(r\"\\s\", \"\", m.group(0).lower())\n        (ends if tok in (\"[/inst]\", \"<</sys>>\", \"</start_of_turn>\", \"<end_of_turn>\", \"<eos>\", \"</assistant>\", \"</system>\", \"<im_end>\", \"</im_start>\") else specials).append(m.group(0))\n        return \" \"\n\n    out = _OTHER_SPECIAL.sub(other, out)\n\n    def turn(m: re.Match) -> str:\n        ends.append(m.group(0).strip())\n        return \"\\n\" + m.group(1) + \" said:\"   # keep the words, drop the turn boundary\n\n    out = _TURN.sub(turn, out)\n    # \"</s>\" ends a turn for many models; a lone one (not closing an HTML <s>) is an end sequence.\n    if _EOS_S.search(out) and out.count(\"<s>\") < out.count(\"</s>\"):\n        ends += _EOS_S.findall(out)\n        out = _EOS_S.sub(\" \", out)\n\n    findings = []\n    if ends:\n        findings.append(Finding(\"PIT-T-07\", f\"{len(ends)} end-of-turn sequence(s) removed ({', '.join(sorted(set(ends))[:4])}).\",\n                                short(text), short(out), count=len(ends)))\n    if specials:\n        findings.append(Finding(\"PIT-T-48\", f\"{len(specials)} special token(s) of a model's chat format removed ({', '.join(sorted(set(specials))[:4])}).\",\n                                short(text), short(out), count=len(specials)))\n    return (re.sub(r\"[ \\t]{2,}\", \" \", out) if findings else text), findings\n", "vid/input_layer/signals.py": "\"\"\"Surface signals Vid shows beyond the 42 codes, still pure observation and\ndeterministic, never the PSE reading (docs/REFERENCE.md Sec 3, first letters;\nSec 4, transform-and-execute). These carry SIG- codes, not PIT codes.\"\"\"\n\nfrom __future__ import annotations\n\nimport re\n\nfrom vid.input_layer.textscore import plausible, segmented_share\nfrom vid.input_layer.types import Finding, short\n\n_WORD = re.compile(r\"[^\\W\\d_]+\", re.UNICODE)\n\n\ndef _first_letters(units: list[str]) -> str:\n    out = []\n    for u in units:\n        for ch in u:\n            if ch.isalpha():\n                out.append(ch)\n                break\n    return \"\".join(out)\n\n\ndef _despace(s: str) -> str:\n    return \"\".join(s.split()).lower()\n\n\ndef acrostic(text: str) -> list[Finding]:  # not yet wired; needs a word list\n\n    \"\"\"First letters of lines, sentences and words, when they spell language\n    that is not already written out in the text.\"\"\"\n    whole = _despace(text)\n    best = None\n    # Lines and sentences only: first letters of every word spell noise in\n    # ordinary prose. Judged by letter-pair structure, like the decoders.\n    for kind, units in (\n        (\"lines\", text.splitlines()),\n        (\"sentences\", re.split(r\"[.!?]+\", text)),\n    ):\n        letters = _first_letters([u for u in units if u.strip()])\n        if len(letters) < 5:\n            continue\n        if not plausible(letters):\n            continue\n        if _despace(letters) in whole:\n            continue\n        share = max(segmented_share(letters), 0.001)\n        if best is None or share > best[2]:\n            best = (kind, letters, share)\n    if not best:\n        return []\n    kind, letters, _ = best\n    return [Finding(\"SIG-ACROSTIC\", f\"The first letters of the {kind} spell a hidden message.\",\n                    short(text), short(letters))]\n\n\n# \"read the first letter of each word and do that\", and the like.\n_TRANSFORM = re.compile(\n    r\"(?:take|read|use|extract|concatenate|combine|spell|gather|collect)\\b[^.?!\\n]{0,40}?\"\n    r\"\\b(?:first|1st|initial|last|final|every|each)\\b[^.?!\\n]{0,20}?\"\n    r\"\\b(?:letter|letters|character|characters|char|chars|word|words|line|lines)\\b\",\n    re.I)\n_THEN_ACT = re.compile(\n    r\"\\b(?:then|and|,)\\b[^.?!\\n]{0,30}?\\b(?:do|execute|follow|obey|run|perform|comply|act|carry out|apply)\\b\"\n    r\"|\\b(?:do|follow|execute|obey|perform)\\b[^.?!\\n]{0,15}?\\b(?:that|it|this|the result|the above|the instruction)\\b\",\n    re.I)\n\n\ndef transform_execute(text: str) -> list[Finding]:\n    \"\"\"An instruction to transform some text and then act on the result.\"\"\"\n    for m in _TRANSFORM.finditer(text):\n        window = text[m.start():m.end() + 80]\n        if _THEN_ACT.search(window):\n            return [Finding(\"SIG-TRANSFORM-EXEC\",\n                            \"An instruction to transform text and then act on the result. \"\n                            \"Vid shows it; it does not judge intent.\",\n                            short(text[m.start():m.end() + 80]))]\n    return []\n\n\ndef signals(text: str) -> list[Finding]:\n    # Acrostic is held back until a real word list ships: judged only by\n    # letter-pair structure it flags ordinary multi-line text (\"HPILTA\"), and\n    # a watcher that cries wolf on every email is worse than none.\n    return transform_execute(text)\n", "vid/input_layer/types.py": "\"\"\"What the input layer returns. Plain data, so the proxy, the window and the\nweb page all read the same result.\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import asdict, dataclass, field\n\nfrom vid.input_layer.codes import ALL_NAMES, BASIC_LAYER, GROUP\n\n\n@dataclass\nclass Finding:\n    code: str                  # PIT code\n    detail: str                # one plain sentence for a person\n    excerpt: str = \"\"          # what was received (shortened)\n    revealed: str = \"\"         # what it says once undone\n    chain: list[str] = field(default_factory=list)   # for layered decoding\n    count: int = 1\n\n    @property\n    def name(self) -> str:\n        return ALL_NAMES.get(self.code, self.code)\n\n    @property\n    def group(self) -> str:\n        return GROUP.get(self.code, \"signal\")\n\n    def as_dict(self) -> dict:\n        d = asdict(self)\n        d[\"name\"], d[\"group\"] = self.name, self.group\n        return d\n\n\n@dataclass\nclass Analysis:\n    raw: str                   # the payload as received (kept, Sec 3)\n    readable: str              # what it says once everything is undone\n    findings: list[Finding]\n    provenance: str = \"external\"\n\n    @property\n    def hidden(self) -> bool:\n        \"\"\"True when something was concealed. Flattening a structure is\n        ordinary reading, not concealment, so it alone does not count.\"\"\"\n        return any(f.group != \"structure\" for f in self.findings)\n\n    def codes(self) -> list[str]:\n        return sorted({f.code for f in self.findings})\n\n    def as_dict(self) -> dict:\n        return {\"provenance\": self.provenance, \"readable\": self.readable, \"hidden\": self.hidden,\n                \"codes\": self.codes(), \"findings\": [f.as_dict() for f in self.findings]}\n\n\ndef short(s: str, n: int = 120) -> str:\n    s = s.replace(\"\\n\", \"⏎\")\n    return s if len(s) <= n else s[: n - 1] + \"…\"\n"};
